'use strict';
const API_BASE=(window.SPORTFIT_CONFIG?.apiBaseUrl||'').replace(/\/$/,'');
const API_MISSING=location.hostname.endsWith('.github.io')&&!API_BASE;
let sessionId=sessionStorage.getItem('sportfit-session')||'';
async function serverFetch(path,options={}){const headers=new Headers(options.headers||{});if(sessionId)headers.set('X-Auth-Token',sessionId);const res=await fetch(API_BASE+path,{...options,headers,credentials:'omit'});const next=res.headers.get('X-Auth-Token');if(next!==null){sessionId=next;if(next)sessionStorage.setItem('sportfit-session',next);else sessionStorage.removeItem('sportfit-session');}return res;}

const $=(s,el=document)=>el.querySelector(s), $$=(s,el=document)=>[...el.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',activity:'M2 12h5l3-8 4 16 3-8h5',chart:'M4 3v17h17 M8 15l4-5 4 2 5-7',calendar:'M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2z M7 3v4 M17 3v4 M3 11h18 M8 15h2 M14 15h2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',trophy:'M8 3h8v6a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 13v6 M8 21h8 M9 19h6',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2 M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',arrow:'M5 12h14 M13 6l6 6-6 6',chevron:'M9 5l7 7-7 7',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',flame:'M12 3c2 5 7 6 7 12a7 7 0 0 1-14 0c0-4 3-6 3-6s-1 4 2 5c2-3 2-6 2-11z',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 10v4 M10 12h4',play:'M8 4l12 8-12 8z',pause:'M8 4v16 M16 4v16',stop:'M6 6h12v12H6z',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',save:'M6 3h12v18l-6-4-6 4z',logout:'M9 4H4v16h5 M9 12h12 M16 7l5 5-5 5',leaf:'M20 3C8 2 2 9 6 16s16 6 14-13z M5 21l10-11',water:'M12 3s-7 8-7 13a7 7 0 0 0 14 0c0-5-7-13-7-13z',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',edit:'M15 5l4 4 M4 20l4-1L21 6l-4-4L4 15z',trash:'M3 6h18 M8 6V3h8v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',menu:'M3 6h18 M3 12h18 M3 18h18',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',shield:'M12 3l8 3v6c0 6-8 10-8 10S4 18 4 12V6z M8 12l3 3 5-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.activity}"/></svg>`;
const activities=[
{id:'running',name:'Running',type:'Cardio',intensity:'High',duration:30,met:9.8,level:'Intermediate',equipment:'Running shoes',desc:'Find your rhythm, build endurance, and take the scenic route.'},
{id:'walking',name:'Walking',type:'Cardio',intensity:'Low',duration:30,met:3.5,level:'Beginner',equipment:'Comfortable walking shoes',desc:'A little fresh air and a steady pace. Every step counts.'},
{id:'cycling',name:'Cycling',type:'Cardio',intensity:'Medium',duration:45,met:7.5,level:'Intermediate',equipment:'Bicycle, helmet',desc:'Explore new paths while building strength and stamina.'},
{id:'swimming',name:'Swimming',type:'Cardio',intensity:'High',duration:30,met:8,level:'Intermediate',equipment:'Pool, swimwear, goggles',desc:'Move through the water with a low-impact, full-body session.'},
{id:'football',name:'Football',type:'Team sports',intensity:'High',duration:60,met:7,level:'Intermediate',equipment:'Football, boots, pitch',desc:'Build agility and teamwork with the beautiful game.'},
{id:'basketball',name:'Basketball',type:'Team sports',intensity:'High',duration:45,met:7,level:'Intermediate',equipment:'Basketball, court, trainers',desc:'Work on your skills, coordination, and explosive movement.'},
{id:'yoga',name:'Yoga',type:'Mind & body',intensity:'Low',duration:25,met:2.5,level:'Beginner',equipment:'Yoga mat',desc:'Breathe deeply, find your balance, and make space for yourself.'},
{id:'strength',name:'Strength training',type:'Strength',intensity:'Medium',duration:40,met:5,level:'Intermediate',equipment:'Dumbbells or resistance bands',desc:'Build a stronger foundation, one considered rep at a time.'},
{id:'aerobic',name:'Aerobic exercise',type:'Cardio',intensity:'High',duration:30,met:7,level:'Beginner',equipment:'Trainers, open floor space',desc:'Get your heart moving with a joyful, energising workout.'},
{id:'stretching',name:'Stretching & mobility',type:'Mind & body',intensity:'Low',duration:15,met:2.5,level:'Beginner',equipment:'Exercise mat',desc:'Release tension and improve your range of motion.'}
];
const activity=id=>activities.find(a=>a.id===id)||activities[0];
const nav=[['overview','grid','Overview'],['activities','activity','Explore activities'],['tracker','play','Workout tracker'],['analytics','chart','My progress'],['planner','calendar','Workout planner'],['wellness','heart','Health & wellness'],['achievements','trophy','Achievements'],['profile','user','My profile']];
let state=null, csrf=null, charts=[], current='overview', authMode='login', period='week', filters={type:'All activities',intensity:'All intensities',duration:'Any duration',search:'',saved:false}, weekOffset=0, restUntil=0;
let workout={activity:'running',status:'idle',elapsed:0,since:0,reps:0,sets:0,distance:0,target:30}, gpsId=null,lastPosition=null,activeOwner=null;
let resetToken='';
function captureResetLink(){if(!location.hash.startsWith('#reset-password?'))return false;resetToken=new URLSearchParams(location.hash.split('?')[1]).get('token')||'';authMode='reset';history.replaceState(null,'',location.pathname+location.search+'#reset-password');return true;}
captureResetLink();
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateAt=(s)=>new Date(s+'T12:00:00');
const niceDate=(s,options={month:'short',day:'numeric'})=>new Date(s).toLocaleDateString('en-US',options);
const clock=s=>`${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const minutes=ws=>ws.reduce((n,w)=>n+w.duration/60,0);
const calories=ws=>ws.reduce((n,w)=>n+w.calories,0);
const monday=(offset=0)=>{let d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7)+offset*7);return d;};
const weekWorkouts=()=>state.workouts.filter(w=>new Date(w.endedAt)>=monday());
const streak=()=>{const dates=new Set(state.workouts.map(w=>localDate(new Date(w.endedAt))));let d=new Date(),n=0;if(!dates.has(localDate(d)))d.setDate(d.getDate()-1);while(dates.has(localDate(d))){n++;d.setDate(d.getDate()-1);}return n;};
const pct=()=>Math.min(100,Math.round(weekWorkouts().length/state.profile.weeklyTarget*100));
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.className='',4200);}
async function getCsrf(){csrf=await (await serverFetch('/api/csrf')).json();}
async function api(url,method='GET',body){if(!csrf)await getCsrf();const headers={};if(method!=='GET')headers[csrf.headerName]=csrf.token;if(body)headers['Content-Type']='application/json';const res=await serverFetch('/api'+url,{method,headers,body:body?JSON.stringify(body):undefined});if(res.status===401){state=null;renderAuth();throw Error('Please sign in to continue.');}if(!res.ok){let d;try{d=await res.json();}catch{}throw Error(d?.error||`Request failed (${res.status}). Please try again.`);}if(res.status===204)return;return res.json();}
async function refresh(){state=await api('/state');}
function destroyCharts(){charts.forEach(c=>c.destroy());charts=[];}
function chart(id,type,data,options={}){const el=$('#'+id);if(!el||!window.Chart)return;charts.push(new Chart(el,{type,data,options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{backgroundColor:'#254c3e',padding:10,cornerRadius:6}},scales:type==='doughnut'?{}:{x:{grid:{display:false},border:{display:false},ticks:{color:'#92998d',font:{size:10}}},y:{beginAtZero:true,border:{display:false},grid:{color:'#f0f2ed'},ticks:{maxTicksLimit:5,color:'#92998d',font:{size:9}}}},...options}}));}
function initials(){return esc(state.profile.name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase());}
const brand=()=>`<a class="brand" href="#overview"><span class="brand-symbol">ϟ</span><span>SportFit<small>PRO</small></span></a>`;
function renderAuth(){
 destroyCharts();const recovering=['forgot','reset','reset-sent'].includes(authMode);
 const title={login:'Welcome back.',register:'Your next chapter starts here.',forgot:'Let’s get you back in.',reset:'A fresh start.', 'reset-sent':'Check your inbox.'}[authMode]||'Welcome back.';
 const subtitle={login:'A little progress, every day. Let’s keep it going.',register:'Build a routine that feels like you.',forgot:'Enter your account email and we’ll send a reset link.',reset:'Choose a new password for your SportFit Pro account.', 'reset-sent':'If an account exists for that email, a reset link will arrive shortly. Check your spam folder too.'}[authMode]||'';
 const error=API_MISSING?'The website is deployed. The account server still needs to be connected.':authMode==='reset'&&!resetToken?'Open the reset link from your email, or request a new one.':'';
 let fields='';
 if(authMode==='register')fields+=`<div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" placeholder="Alex Morgan" required maxlength="80"></div>`;
 if(['login','register','forgot'].includes(authMode))fields+=`<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254"></div>`;
 if(['login','register','reset'].includes(authMode))fields+=`<div class="field"><label for="password">${authMode==='reset'?'New password':'Password'}</label><input id="password" name="password" type="password" autocomplete="${authMode==='login'?'current-password':'new-password'}" placeholder="${authMode==='login'?'Your password':'At least 8 characters'}" minlength="8" maxlength="72" required></div>`;
 if(authMode==='reset')fields+=`<div class="field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" name="confirmPassword" type="password" autocomplete="new-password" minlength="8" maxlength="72" required></div>`;
 const labels={login:'Sign in to your space',register:'Create your account',forgot:'Send reset link',reset:'Save new password'};
 $('#app').innerHTML=`<main class="auth"><section class="auth-picture"><img src="./images/hero.jpg" alt="Athletes running along a mountain trail at sunrise">${brand()}<div class="auth-copy"><div class="caps">SMALL STEPS. STRONGER YOU.</div><h1>Your everyday,<br>stronger.</h1><p>A space for your movement, your goals, and everything that makes you feel good.</p></div></section><section class="auth-form-side"><div class="auth-form-inner"><div class="caps">YOUR PERSONAL FITNESS SPACE</div><h2>${title}</h2><p>${subtitle}</p>${recovering?'':`<div class="auth-tabs"><button class="${authMode==='login'?'active':''}" data-auth="login">Sign in</button><button class="${authMode==='register'?'active':''}" data-auth="register">Create account</button></div>`}${authMode==='reset-sent'?`<p class="auth-note">Reset links expire in 30 minutes and work once. For your privacy, we don’t confirm whether an email is registered.</p><button class="btn" data-auth="login">Back to sign in ${icon('arrow')}</button>`:`<form id="auth-form">${fields}<p class="form-error" id="auth-error" role="alert">${error}</p><button class="btn" type="submit" ${API_MISSING||(authMode==='reset'&&!resetToken)?'disabled':''}>${labels[authMode]||labels.login} ${icon('arrow')}</button></form>`}${authMode==='login'?`<button class="forgot-link" data-auth="forgot">Forgot password?</button>`:''}${['forgot','reset'].includes(authMode)?`<div class="recovery-links"><button data-auth="login">Back to sign in</button>${authMode==='reset'?'<button data-auth="forgot">Request a new link</button>':''}</div>`:''}<p class="auth-note">${icon('shield')} ${recovering?'Your reset link is private. We never ask for your old password to recover your account.':'Your journey is personal. Your account keeps your workouts, plans, and wellness records together.'}</p></div></section></main>`;
}
function shell(){const item=nav.find(n=>n[0]===current);$('#app').innerHTML=`<div class="mobile-shade"></div><aside class="sidebar">${brand()}<div class="nav-label caps">YOUR FITNESS SPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,i,t])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(i)}${t}${current===id?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note">${icon('leaf')}<h3>Better, a little every day.</h3><p>You don’t have to be perfect.<br>You just have to keep showing up.</p><button data-action="navigate" data-page="planner">Make a little plan ${icon('arrow')}</button></div><div class="sidebar-footer"><span class="avatar">${initials()}</span><div><strong>${esc(state.profile.name.split(' ')[0])}</strong><small>Your personal account</small></div><button data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Your workspace</span>${icon('chevron')}<strong>${item[2]}</strong></div><div class="top-actions"><span class="date">${icon('calendar')} &nbsp; ${niceDate(new Date(),{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</span><span class="divider"></span><button class="round" data-action="reminders" aria-label="View workout reminders">${icon('bell')}</button><a class="avatar" href="#profile" aria-label="My profile">${initials()}</a></div></header><main class="content" id="content"></main></div>`;}
const footer=()=>`<footer class="page-footer"><span>© ${new Date().getFullYear()} SportFit Pro. Every move matters.</span><span>Made for a healthier, happier you ${icon('leaf')}</span></footer>`;
function pageHead(title,subtitle,button=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`;}
function statCards(){const ws=state.workouts;return `<div class="stats"><div class="stat"><div class="stat-top">Total workouts<span class="stat-icon">${icon('activity')}</span></div><div class="stat-value">${ws.length}<span>sessions</span></div><div class="stat-foot"><b>${weekWorkouts().length} this week</b> · keep showing up</div></div><div class="stat"><div class="stat-top">Active minutes<span class="stat-icon">${icon('clock')}</span></div><div class="stat-value">${Math.round(minutes(ws)).toLocaleString()}<span>min</span></div><div class="stat-foot"><b>${Math.round(minutes(weekWorkouts()))} min</b> of movement this week</div></div><div class="stat"><div class="stat-top">Calories burned<span class="stat-icon">${icon('flame')}</span></div><div class="stat-value">${calories(ws).toLocaleString()}<span>kcal</span></div><div class="stat-foot">An estimate based on your activity</div></div><div class="stat"><div class="stat-top">Current streak<span class="stat-icon">${icon('target')}</span></div><div class="stat-value">${streak()}<span>days</span></div><div class="stat-foot"><b>${pct()}% of weekly goal</b> · one day at a time</div></div></div>`;}
function activityCard(a){const saved=state.profile.savedActivities.includes(a.id);return `<article class="activity-card"><div class="activity-photo"><img src="./images/${a.id}.jpg" alt="${esc(a.name)} exercise" loading="lazy"><span class="tag">${a.type}</span><button class="save ${saved?'saved':''}" data-action="save-activity" data-id="${a.id}" aria-label="${saved?'Unsave':'Save'} ${esc(a.name)}" aria-pressed="${saved}">${icon('save')}</button></div><div class="activity-body"><h3>${a.name}</h3><div class="activity-meta"><span>${icon('clock')}${a.duration} min</span><span>${icon('flame')}~${Math.round(a.met*3.5*state.profile.weight/200*a.duration)} kcal</span></div><p class="activity-desc">${a.desc}</p>${current==='activities'?`<p class="activity-desc">${a.level} · ${a.intensity} intensity<br>Equipment: ${a.equipment}</p>`:''}<div class="activity-bottom"><span>${a.intensity} intensity</span><button data-action="start-activity" data-id="${a.id}">Start activity ${icon('arrow')}</button></div></div></article>`;}
function periodSelector(){return `<div class="segment" aria-label="Reporting period">${[['day','Daily'],['week','Weekly'],['month','Monthly']].map(([id,name])=>`<button data-action="period" data-id="${id}" class="${period===id?'active':''}" aria-pressed="${period===id}">${name}</button>`).join('')}</div>`;}
function ring(){let done=weekWorkouts().length,goal=state.profile.weeklyTarget;return `<div class="goal-ring"><svg viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="66"/><circle class="progress" cx="80" cy="80" r="66" stroke-dasharray="414.69" stroke-dashoffset="${414.69*(1-pct()/100)}"/></svg><div class="ring-copy"><strong>${done}<span style="font-size:18px"> / ${goal}</span></strong><span>workouts completed</span></div></div>`;}
function overview(){const next=state.plans.filter(p=>!p.completed&&p.date>=localDate()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,2);return pageHead(`Let’s move, ${esc(state.profile.name.split(' ')[0])} <span style="font-size:23px">✦</span>`,`Here’s a little snapshot of your journey. Make today feel good.`,`<button class="btn" data-action="start-activity" data-id="${workout.activity}">${icon('plus')} Start a workout</button>`)+`<section class="hero"><img src="./images/hero.jpg" alt="Trail runners finding their stride at sunrise"><div class="hero-copy"><div class="eyebrow">YOUR PACE. YOUR PROGRESS.</div><h2>A little movement.<br>A stronger you.</h2><p>Find an activity you love, build your rhythm, and feel a little better every day.</p><a class="btn lime" href="#activities">Find your next activity ${icon('arrow')}</a></div><div class="hero-tag"><i></i> EVERY MOVE MATTERS</div></section>`+statCards()+`<div class="overview-grid"><div><section class="panel"><div class="panel-head"><div><h2>Your activity at a glance</h2><p>A little consistency goes a long way.</p></div>${periodSelector()}</div><div class="chart-wrap"><canvas id="overview-chart" aria-label="Exercise minutes over time" role="img"></canvas></div></section><div class="section-head"><h2>Find your kind of movement</h2><a href="#activities">Explore all ${icon('arrow')}</a></div><div class="activity-grid overview-activities">${['running','yoga','strength'].map(id=>activityCard(activity(id))).join('')}</div></div><div class="right-rail"><section class="panel goal-panel"><div class="panel-head"><div><h2>Your weekly goal</h2><p>Small steps. Real progress.</p></div>${icon('target')}</div>${ring()}<p>${pct()>=100?'<b>You did it!</b> Your weekly goal is complete.':`<b>${Math.max(0,state.profile.weeklyTarget-weekWorkouts().length)} workouts to go.</b> You’ve got this.`}</p><div class="week-dots">${Array.from({length:7},(_,i)=>{let d=monday();d.setDate(d.getDate()+i);let done=weekWorkouts().some(w=>localDate(new Date(w.endedAt))===localDate(d));return `<div class="day-dot"><span>${['M','T','W','T','F','S','S'][i]}</span><i class="${done?'done':''}">${done?'✓':'·'}</i></div>`;}).join('')}</div><div class="motivation"><b>Progress over perfection.</b>Even a 10-minute walk is a step in the right direction.</div></section><section class="panel upcoming"><div class="panel-head"><div><h2>Up next in your plan</h2><p>A little time, just for you.</p></div><a class="btn text" href="#planner">${icon('arrow')}</a></div>${next.length?next.map(p=>`<div class="session-row"><img src="./images/${p.activity}.jpg" alt=""><div><strong>${activity(p.activity).name}</strong><small>${niceDate(dateAt(p.date),{weekday:'short',month:'short',day:'numeric'})} · ${p.duration} min</small></div><button data-action="start-activity" data-id="${p.activity}" aria-label="Start ${activity(p.activity).name}">${icon('play')}</button></div>`).join(''):`<div class="empty">Your next chapter is unwritten.<br><a href="#planner">Plan your first session ${icon('arrow')}</a></div>`}</section></div></div>`;}
function explore(){let list=activities.filter(a=>(filters.type==='All activities'||a.type===filters.type)&&(filters.intensity==='All intensities'||a.intensity===filters.intensity)&&(filters.duration==='Any duration'||(filters.duration==='30 minutes or less'?a.duration<=30:a.duration>30))&&a.name.toLowerCase().includes(filters.search.toLowerCase())&&(!filters.saved||state.profile.savedActivities.includes(a.id)));return pageHead('Find your kind of movement.','Ten ways to move. A whole world of possibilities.')+`<div class="filters"><button class="filter-chip ${!filters.saved?'active':''}" data-action="activity-tab" data-id="all">All activities</button><button class="filter-chip ${filters.saved?'active':''}" data-action="activity-tab" data-id="saved">${icon('save')} My activities (${state.profile.savedActivities.length})</button><label class="visually-hidden" for="type-filter">Activity type</label><select id="type-filter" data-filter="type" style="width:auto">${['All activities','Cardio','Mind & body','Strength','Team sports'].map(t=>`<option ${filters.type===t?'selected':''}>${t}</option>`).join('')}</select><label class="visually-hidden" for="intensity-filter">Intensity</label><select id="intensity-filter" data-filter="intensity" style="width:auto">${['All intensities','Low','Medium','High'].map(t=>`<option ${filters.intensity===t?'selected':''}>${t}</option>`).join('')}</select><label class="visually-hidden" for="duration-filter">Duration</label><select id="duration-filter" data-filter="duration" style="width:auto">${['Any duration','30 minutes or less','Over 30 minutes'].map(t=>`<option ${filters.duration===t?'selected':''}>${t}</option>`).join('')}</select><label class="visually-hidden" for="activity-search">Search activities</label><input class="search" id="activity-search" type="search" placeholder="Search activities…" value="${esc(filters.search)}"></div><div class="activity-grid" id="activity-results">${list.map(activityCard).join('')}</div>${!list.length?'<div class="empty">No activities match these filters. Try another combination.</div>':''}<p class="safety section-gap">Calorie figures are estimates for your profile weight. Actual energy use varies with pace, technique, and individual factors.</p>`;}
function elapsed(){return workout.elapsed+(workout.status==='running'?(Date.now()-workout.since)/1000:0);}
function persistWorkout(){try{localStorage.setItem('sportfit-workout:'+activeOwner,JSON.stringify({...workout,elapsed:elapsed(),since:Date.now()}));}catch{}}
function tracker(){const a=activity(workout.activity);return pageHead('Your time to move.','One session, one step closer. Let’s make it count.')+`<div class="tracker-grid"><section class="panel"><div class="tracker-visual"><img src="./images/${a.id}.jpg" alt="${a.name}"><h2>${a.name}</h2></div><div class="timer" id="live-timer" aria-live="off">${clock(elapsed())}</div><div class="timer-label" id="tracker-status">${workout.status==='idle'?'READY WHEN YOU ARE':workout.status.toUpperCase()}</div><div class="tracker-controls">${workout.status==='idle'?`<button class="btn" data-action="workout-start">${icon('play')} Start workout</button>`:`<button class="btn" data-action="workout-pause">${icon(workout.status==='running'?'pause':'play')} ${workout.status==='running'?'Pause':'Resume'}</button><button class="btn secondary" data-action="workout-stop">${icon('stop')} Finish & save</button>`}</div><div class="meter" role="progressbar" aria-label="Workout target progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(elapsed()/(workout.target*60)*100))}"><i id="workout-progress" style="width:${Math.min(100,elapsed()/(workout.target*60)*100)}%"></i></div><p class="small muted" style="text-align:center" id="workout-target">${Math.round(elapsed()/60)} of ${workout.target} target minutes</p><div class="counter-row"><div class="counter"><span>REPETITIONS</span><div class="counter-controls"><button data-action="rep-minus" aria-label="Remove repetition">−</button><b id="rep-count">${workout.reps}</b><button data-action="rep-plus" aria-label="Add repetition">+</button></div></div><div class="counter"><span>SETS COMPLETED</span><div class="counter-controls"><button data-action="set-minus" aria-label="Remove set">−</button><b id="set-count">${workout.sets}</b><button data-action="set-plus" aria-label="Add set">+</button></div></div></div><div style="text-align:center"><button class="btn secondary" data-action="rest">${icon('clock')} ${restUntil>Date.now()?'Restart':'Start'} 60-second rest</button><button class="btn text" data-action="cancel-rest" style="margin-left:10px">Clear rest</button></div><div class="rest-label" id="rest-count">${restUntil>Date.now()?`Rest · ${Math.ceil((restUntil-Date.now())/1000)} seconds remaining`:''}</div></section><div class="stack"><section class="panel"><h2>Make it your session</h2><p class="small muted">Choose your movement and a comfortable target.</p><div class="field"><label for="tracker-activity">Activity</label><select id="tracker-activity" ${workout.status!=='idle'?'disabled':''}>${activityOptions(a.id)}</select></div><div class="field"><label for="target-minutes">Target duration (minutes)</label><input id="target-minutes" type="number" min="1" max="300" value="${workout.target}" ${workout.status!=='idle'?'disabled':''}></div><div class="metric-row"><span>Estimated calories</span><b id="live-calories">0 kcal</b></div><div class="metric-row"><span>Distance</span><b id="live-distance">${workout.distance.toFixed(2)} km</b></div><div class="metric-row"><span>Suggested equipment</span><b>${a.equipment}</b></div>${['running','walking','cycling'].includes(a.id)?`<div class="section-gap"><button class="btn secondary" data-action="gps">${icon('pin')} ${gpsId!==null?'Disable':'Enable'} GPS tracking</button><p class="small muted" id="gps-status">${gpsId!==null?'GPS is enabled for this session.':'Optional. Your browser asks for location permission.'}</p></div>`:''}<p class="safety section-gap">GPS works best outdoors. Only total distance is saved; precise coordinates stay in this browser. Calories are estimates.</p></section><section class="panel"><div class="stat-icon">${icon('heart')}</div><h3 class="section-gap">A little care goes a long way.</h3><p class="small muted">Warm up for 5 minutes. Keep water nearby, move at your own pace, and cool down gently when you finish. Stop if you feel pain, dizziness, or unusual shortness of breath.</p><a class="btn text" href="#wellness">Check in with yourself ${icon('arrow')}</a></section></div></div>`;}
function activityOptions(selected){return activities.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${a.name}</option>`).join('');}
function chartData(){const now=new Date();let buckets=[];if(period==='day'){for(let i=0;i<24;i++)buckets.push({label:i%3===0?`${i}:00`:'',match:d=>localDate(d)===localDate(now)&&d.getHours()===i});}else if(period==='week'){for(let i=0;i<7;i++){const d=monday();d.setDate(d.getDate()+i);const key=localDate(d);buckets.push({label:d.toLocaleDateString('en-US',{weekday:'short'}),match:t=>localDate(t)===key});}}else{for(let i=1;i<=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();i++){const key=localDate(new Date(now.getFullYear(),now.getMonth(),i));buckets.push({label:String(i),match:t=>localDate(t)===key});}}return {labels:buckets.map(b=>b.label),mins:buckets.map(b=>Math.round(minutes(state.workouts.filter(w=>b.match(new Date(w.endedAt))))*10)/10),counts:buckets.map(b=>state.workouts.filter(w=>b.match(new Date(w.endedAt))).length),cals:buckets.map(b=>calories(state.workouts.filter(w=>b.match(new Date(w.endedAt)))))};}
function renderOverviewChart(){const d=chartData();chart('overview-chart','bar',{labels:d.labels,datasets:[{label:'Active minutes',data:d.mins,backgroundColor:d.mins.map((_,i)=>i===new Date().getDay()-1?'#294f3c':'#dce9c6'),hoverBackgroundColor:'#719260',borderRadius:5,maxBarThickness:30}]});}
function analytics(){return pageHead('Look how far you’ve come.','Your effort, reflected. Every session is part of the story.',`<button class="btn secondary" data-action="export">${icon('download')} Export report</button>`)+statCards()+`<div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>Your movement over time</h2><p>Recorded exercise minutes</p></div>${periodSelector()}</div><div class="chart-wrap tall"><canvas id="trend-chart" role="img" aria-label="Activity minutes trend"></canvas></div></section><section class="panel"><div class="panel-head"><div><h2>Your movement mix</h2><p>All recorded sessions by sport</p></div></div><div class="chart-wrap tall"><canvas id="mix-chart" role="img" aria-label="Activity distribution"></canvas></div>${state.workouts.length?'':'<p class="small muted" style="text-align:center">Complete your first workout to build your picture.</p>'}</section><section class="panel"><div class="panel-head"><div><h2>Energy & consistency</h2><p>Estimated calories and workout frequency</p></div></div><div class="chart-wrap"><canvas id="calorie-chart" role="img" aria-label="Calories and sessions by reporting period"></canvas></div></section><section class="panel"><h2>Your weekly intention</h2>${ring()}<p class="small muted" style="text-align:center">${pct()}% of your ${state.profile.weeklyTarget}-session goal</p>${comparison()}</section></div><section class="panel section-gap"><div class="panel-head"><div><h2>Your activity journal</h2><p>Real movement. Recorded here.</p></div><span class="tag">${state.workouts.length} sessions</span></div>${historyTable()}</section>`;}
function comparison(){const thisWeek=minutes(weekWorkouts());const start=monday(-1),end=monday();const prev=minutes(state.workouts.filter(w=>new Date(w.endedAt)>=start&&new Date(w.endedAt)<end));return `<div class="metric-row"><span>This week</span><b>${Math.round(thisWeek)} min</b></div><div class="metric-row"><span>Last week</span><b>${Math.round(prev)} min</b></div><p class="small muted section-gap">${prev?`${Math.round((thisWeek-prev)/prev*100)}% change in active minutes from last week.`:'Your first week becomes the starting point for future comparisons.'}</p>`;}
function historyTable(){return !state.workouts.length?`<div class="empty">${icon('activity')}Your journal starts with one session.<br><a href="#tracker">Start a workout</a></div>`:`<div class="table-wrap"><table><thead><tr><th>Activity</th><th>Date</th><th>Duration</th><th>Est. calories</th><th>Reps / sets</th><th>Distance</th></tr></thead><tbody>${[...state.workouts].sort((a,b)=>b.endedAt.localeCompare(a.endedAt)).map(w=>`<tr><td><div class="table-activity"><img src="./images/${w.activity}.jpg" alt="">${activity(w.activity).name}</div></td><td>${niceDate(w.endedAt)}</td><td>${clock(w.duration)}</td><td>${w.calories} kcal</td><td>${w.reps} / ${w.sets}</td><td>${w.distance.toFixed(2)} km</td></tr>`).join('')}</tbody></table></div>`;}
function renderAnalyticsCharts(){const d=chartData();chart('trend-chart','line',{labels:d.labels,datasets:[{label:'Exercise minutes',data:d.mins,borderColor:'#42674d',backgroundColor:'#edf3e2',fill:true,tension:.35,pointRadius:3,pointBackgroundColor:'#42674d'}]});const mix=activities.map(a=>({name:a.name,n:state.workouts.filter(w=>w.activity===a.id).length})).filter(a=>a.n);chart('mix-chart','doughnut',{labels:mix.map(a=>a.name),datasets:[{data:mix.map(a=>a.n),backgroundColor:['#294f3c','#abc782','#d6e9ac','#ce9a71','#7c9e86','#d6cf99','#709e9c','#a5b5a0','#9d8b66','#c4d5b0'],borderWidth:4,borderColor:'#fff'}]},{cutout:'72%',plugins:{legend:{display:true,position:'bottom',labels:{boxWidth:8,boxHeight:8,usePointStyle:true,padding:14,font:{size:10},color:'#798571'}}}});chart('calorie-chart','bar',{labels:d.labels,datasets:[{label:'Estimated kcal',data:d.cals,backgroundColor:'#c6dab0',borderRadius:4},{label:'Sessions',data:d.counts,type:'line',borderColor:'#365b43',yAxisID:'sessions',pointRadius:3}]},{scales:{x:{grid:{display:false},ticks:{font:{size:9}}},y:{beginAtZero:true,grid:{color:'#f0f2eb'},ticks:{font:{size:9}}},sessions:{position:'right',beginAtZero:true,grid:{display:false},ticks:{precision:0,font:{size:9}}}}});}
function recommendedActivities(){const prefs=state.profile.preferences.length?[...state.profile.preferences]:['walking','yoga','strength'];const recent=weekWorkouts();return prefs.sort((a,b)=>recent.filter(w=>w.activity===a).length-recent.filter(w=>w.activity===b).length);}
function recommendation(){const w=todayWellness();if(['tired','sore'].includes(w.recovery)||w.intensity>=8)return 'Your latest check-in suggests a gentler day. Consider stretching, an easy walk, or rest before another demanding session.';const ids=recommendedActivities();return state.workouts.length?`You’ve logged ${weekWorkouts().length} sessions this week. ${activity(ids[0]).name} is one of your less-used preferences this week — a good way to bring variety into your routine.`:'Begin with an activity you enjoy. Your recorded sessions will help us suggest more variety as you go.';}
function planner(){let start=monday(weekOffset),end=new Date(start);end.setDate(end.getDate()+6);return pageHead('A little plan. A lot of possibility.','Make room for movement in a way that works for you.',`<button class="btn" data-action="plan-add">${icon('plus')} Add a session</button>`)+`<div class="two-col" style="grid-template-columns:2fr 1fr;margin-bottom:22px"><section class="panel"><div class="panel-head"><div><h2>Your weekly rhythm</h2><p>${state.profile.level[0].toUpperCase()+state.profile.level.slice(1)} · ${esc(state.profile.objective)}</p></div><span class="tag">${state.profile.weeklyTarget} sessions / week</span></div><p class="small muted">${state.profile.level==='beginner'?'Start gently with 15–25 minute sessions. Alternate movement with rest days as you find your rhythm.':state.profile.level==='intermediate'?'Mix 30–45 minutes of cardio, strength, and recovery. Give yourself a rest day between harder sessions.':'Balance challenging 45–60 minute sessions with lighter movement and planned recovery.'}</p><p class="small muted">${recommendation()}</p><button class="btn secondary" data-action="generate-plan">${icon('calendar')} Generate a personalised week</button></section><section class="panel"><h2>Planned meets done</h2><div class="metric-row"><span>Sessions this week</span><b>${state.plans.filter(p=>p.date>=localDate(start)&&p.date<=localDate(end)).length}</b></div><div class="metric-row"><span>Marked complete</span><b>${state.plans.filter(p=>p.date>=localDate(start)&&p.date<=localDate(end)&&p.completed).length}</b></div><a class="btn text section-gap" href="#profile">Edit your goal ${icon('arrow')}</a></section></div><section class="panel"><div class="panel-head"><div><h2>${niceDate(start)} – ${niceDate(end,{month:'short',day:'numeric',year:'numeric'})}</h2><p>Your seven-day exercise calendar</p></div><div class="segment"><button data-action="week-prev" aria-label="Previous week">←</button><button data-action="week-today">Today</button><button data-action="week-next" aria-label="Next week">→</button></div></div><div class="calendar">${Array.from({length:7},(_,i)=>{let d=new Date(start);d.setDate(d.getDate()+i);const day=localDate(d),sessions=state.plans.filter(p=>p.date===day),rest=state.wellness.some(w=>w.date===day&&w.restDay);return `<div class="calendar-day ${day===localDate()?'today':''}"><div class="calendar-date">${niceDate(d,{weekday:'short'})}<b>${d.getDate()}</b></div>${rest?'<span class="tag">Rest day</span>':''}${sessions.map(p=>`<div class="plan-item ${p.completed?'complete':''}"><strong>${activity(p.activity).name}</strong><small>${p.duration} min · ${p.completed?'Completed':'Planned'}</small><div class="plan-actions"><button data-action="plan-complete" data-id="${p.id}" aria-label="${p.completed?'Reopen':'Complete'} ${activity(p.activity).name}" title="Mark ${p.completed?'incomplete':'complete'}">${icon('check')}</button><button data-action="plan-edit" data-id="${p.id}" aria-label="Edit session">${icon('edit')}</button><button data-action="plan-delete" data-id="${p.id}" aria-label="Delete session">${icon('trash')}</button></div></div>`).join('')}<button class="add-day" data-action="plan-add" data-id="${day}" aria-label="Add session on ${day}">+</button></div>`;}).join('')}</div></section><p class="small muted section-gap">Marking a plan complete updates your calendar. Record a timed workout in the tracker to add duration and calories to your analytics.</p>`;}
function planDialog(id=null,date=null){const p=state.plans.find(p=>p.id===id);const dialog=$('#modal');dialog.innerHTML=`<div class="dialog-head"><h2>${p?'Edit your session':'Make time for movement'}</h2><button data-action="close-dialog" aria-label="Close">×</button></div><form id="plan-form" data-id="${p?.id||''}"><div class="field"><label for="plan-date">Day</label><input id="plan-date" name="date" type="date" value="${p?.date||date||localDate()}" required></div><div class="field"><label for="plan-activity">Activity</label><select id="plan-activity" name="activity">${activityOptions(p?.activity||state.profile.preferences[0]||'running')}</select></div><div class="field"><label for="plan-duration">Duration (minutes)</label><input id="plan-duration" name="duration" type="number" min="5" max="300" value="${p?.duration||30}" required></div><div class="form-error" id="plan-error" role="alert"></div><div class="dialog-actions"><button class="btn secondary" type="button" data-action="close-dialog">Cancel</button><button class="btn" type="submit">Save session ${icon('check')}</button></div></form>`;dialog.showModal();}
function todayWellness(){return state.wellness.find(w=>w.date===localDate())||{date:localDate(),water:0,sleep:0,intensity:3,heartRate:0,recovery:'okay',restDay:false};}
function wellness(){const w=todayWellness();return pageHead('Take care of the whole you.','Movement feels better when you make space for recovery.')+`<div class="wellness-grid"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>A little hydration check</h2><p>Today’s water intake</p></div><span class="stat-icon">${icon('water')}</span></div><div class="water-count">${w.water.toLocaleString()} <small>/ 2,000 ml</small></div><p class="small muted">A general reference. Your needs may vary.</p><div class="water-glasses" aria-label="${w.water} millilitres of water">${Array.from({length:8},(_,i)=>`<span class="glass ${w.water>i*250?'filled':''}"></span>`).join('')}</div><div class="water-actions"><button class="btn" data-action="water-add">${icon('plus')} Add 250 ml</button><button class="btn secondary" data-action="water-remove">− 250 ml</button></div></section><section class="panel"><h2>Your recent check-ins</h2>${state.wellness.length?state.wellness.slice(0,5).map(d=>`<div class="metric-row"><span>${niceDate(dateAt(d.date))}</span><b>${d.water} ml · ${d.sleep}h sleep</b></div>`).join(''):'<p class="empty">Your first check-in starts today.</p>'}</section></div><section class="panel"><img class="recovery-photo" src="./images/recovery.jpg" alt="Water and a yoga mat beside a quiet pool"><h2>How are you feeling today?</h2><p class="small muted">A quick check-in can help you find your balance.</p><form id="wellness-form"><div class="form-grid"><div class="field"><label for="sleep">Sleep last night (hours)</label><input id="sleep" name="sleep" type="number" min="0" max="24" step="0.1" value="${w.sleep}" required></div><div class="field"><label for="intensity">Perceived exercise intensity (1–10)</label><input id="intensity" name="intensity" type="number" min="1" max="10" value="${w.intensity}" required></div><div class="field"><label for="recovery">Recovery self-assessment</label><select id="recovery" name="recovery">${[['great','Rested & ready'],['okay','Feeling okay'],['tired','A little tired'],['sore','Sore — take it gently']].map(([id,t])=>`<option value="${id}" ${w.recovery===id?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="heartRate">Heart rate (bpm, optional)</label><input id="heartRate" name="heartRate" type="number" min="0" max="240" value="${w.heartRate||''}" placeholder="Manual entry"><small>No device connection. Leave blank if unknown.</small></div><div class="field span2"><label style="display:flex;align-items:center;gap:8px"><input name="restDay" type="checkbox" ${w.restDay?'checked':''}> Make today a rest day</label></div></div><button class="btn" type="submit">Save today’s check-in ${icon('check')}</button></form>${wellnessAdvice(w)}</section></div><section class="panel section-gap"><div class="form-grid"><div><h3>Before you move</h3><p class="small muted">Warm up for 5–10 minutes with easy walking and gentle dynamic movements. Increase the pace gradually, and use equipment that fits.</p></div><div><h3>After you move</h3><p class="small muted">Ease down for 5 minutes, then stretch gently without bouncing. Give hard-worked muscles time to recover and prioritise sleep.</p></div></div><p class="safety">SportFit Pro provides general fitness information, not medical advice. BMI, calorie estimates, and wellness indicators are not diagnoses. Stop exercising if you experience pain, dizziness, or unusual breathlessness. Seek qualified advice for health concerns or before a new routine if you have a relevant medical condition.</p></section>`;}
function wellnessAdvice(w){const notes=[];if(w.sleep>0&&w.sleep<7)notes.push('You recorded less than 7 hours of sleep. Consider a gentler session and give yourself time to recover.');if(w.intensity>=8)notes.push('That was a high-intensity effort. Space out demanding workouts, stay hydrated, and allow recovery.');if(['tired','sore'].includes(w.recovery))notes.push('Listen to how you feel. A rest day or gentle mobility may suit you today.');if(weekWorkouts().length>7)notes.push('You’ve recorded many sessions this week. Check that you are balancing training with adequate recovery.');return notes.map(n=>`<div class="notice">${icon('heart')} ${n}</div>`).join('');}
const badges=()=>[{name:'First step',desc:'Complete your first workout.',icon:'play',value:state.workouts.length,target:1},{name:'Finding your rhythm',desc:'Record 5 workout sessions.',icon:'activity',value:state.workouts.length,target:5},{name:'A little every day',desc:'Build a 3-day activity streak.',icon:'flame',value:bestStreak(),target:3},{name:'One hundred minutes',desc:'Record 100 active minutes.',icon:'clock',value:Math.floor(minutes(state.workouts)),target:100},{name:'The explorer',desc:'Try 4 different activities.',icon:'pin',value:new Set(state.workouts.map(w=>w.activity)).size,target:4},{name:'Weekly intention',desc:'Meet your current weekly target.',icon:'target',value:weekWorkouts().length,target:state.profile.weeklyTarget},{name:'Keep showing up',desc:'Complete 20 workout sessions.',icon:'trophy',value:state.workouts.length,target:20},{name:'A balanced routine',desc:'Record 7 wellness check-ins.',icon:'heart',value:state.wellness.length,target:7}];
function bestStreak(){const dates=[...new Set(state.workouts.map(w=>localDate(new Date(w.endedAt))))].sort();let best=0,n=0,prev=null;for(const s of dates){const d=dateAt(s);n=prev&&Math.round((d-prev)/86400000)===1?n+1:1;best=Math.max(best,n);prev=d;}return best;}
function achievements(){const b=badges();return pageHead('Small wins. Big feelings.','Every effort counts. Here’s to the progress you’re making.',`<button class="btn secondary" data-action="export">${icon('download')} Download activity report</button>`)+`<div class="report-intro"><div class="caps" style="color:var(--lime);margin-bottom:12px">YOUR JOURNEY, SO FAR</div><h2>You’ve earned ${b.filter(x=>x.value>=x.target).length} of ${b.length} achievements.</h2><p>${state.workouts.length?'Your consistency is becoming a story worth celebrating. Keep moving in your own way.':'Your first achievement is one workout away. Start small, and make it yours.'}</p></div><div class="badge-grid">${b.map(x=>`<article class="badge-card ${x.value<x.target?'locked':''}"><div class="badge-medal">${icon(x.icon)}</div><h3>${x.name}</h3><p>${x.desc}</p><span class="tag">${x.value>=x.target?'✓ Earned':`${Math.min(x.value,x.target)} / ${x.target}`}</span><div class="meter"><i style="width:${Math.min(100,x.value/x.target*100)}%"></i></div></article>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><div><h2>Your personal activity report</h2><p>Saved workouts, calculated progress, and a record you can keep.</p></div><button class="btn text" data-action="export">Download CSV ${icon('download')}</button></div>${historyTable()}</section>`;}
function profile(){const p=state.profile;return pageHead('A routine that feels like you.','Your goals, your starting point, your own kind of progress.')+`<div class="two-col"><section class="panel"><h2>Your fitness profile</h2><p class="small muted">These details help personalise your plans and estimates.</p><form id="profile-form"><div class="form-grid"><div class="field span2"><label for="profile-name">Your name</label><input id="profile-name" name="name" value="${esc(p.name)}" maxlength="80" required></div><div class="field"><label for="profile-email">Email address</label><input id="profile-email" value="${esc(state.email)}" readonly type="email"></div><div class="field"><label for="age">Age</label><input id="age" name="age" type="number" min="13" max="120" value="${p.age}" required></div><div class="field"><label for="height">Height (cm)</label><input id="height" name="height" type="number" min="80" max="250" step="0.1" value="${p.height}" required></div><div class="field"><label for="weight">Weight (kg)</label><input id="weight" name="weight" type="number" min="25" max="350" step="0.1" value="${p.weight}" required></div><div class="field"><label for="level">Fitness level</label><select id="level" name="level">${['beginner','intermediate','advanced'].map(l=>`<option value="${l}" ${l===p.level?'selected':''}>${l[0].toUpperCase()+l.slice(1)}</option>`).join('')}</select></div><div class="field"><label for="weeklyTarget">Weekly workout target</label><input id="weeklyTarget" name="weeklyTarget" type="number" min="1" max="21" value="${p.weeklyTarget}" required></div><div class="field span2"><label for="objective">Your personal fitness objective</label><textarea id="objective" name="objective" rows="2" maxlength="300">${esc(p.objective)}</textarea></div><div class="field span2"><label>Activities you enjoy</label><div class="check-list">${activities.map(a=>`<label><input type="checkbox" name="preferences" value="${a.id}" ${p.preferences.includes(a.id)?'checked':''}>${a.name}</label>`).join('')}</div></div></div><button class="btn" type="submit">Save your profile ${icon('check')}</button></form></section><div class="stack"><section class="panel"><div class="panel-head"><div><h2>A little body context</h2><p>Body Mass Index (BMI)</p></div><span class="stat-icon">${icon('user')}</span></div><div class="bmi" id="bmi-value">${(p.weight/(p.height/100)**2).toFixed(1)}</div><p class="small muted" id="bmi-caption">Calculated from ${p.height} cm and ${p.weight} kg.</p><div class="meter"><i style="width:60%"></i></div><p class="safety">BMI is a general screening calculation, not a diagnosis. It does not measure body composition or account for every individual factor, and adult thresholds do not apply to children. Discuss personal health questions with a qualified professional.</p></section><section class="panel"><h2>Keep your account secure</h2><p class="small muted">Choose a password you don’t use elsewhere.</p><form id="password-form"><div class="field"><label for="currentPassword">Current password</label><input id="currentPassword" name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label for="newPassword">New password</label><input id="newPassword" name="newPassword" type="password" autocomplete="new-password" minlength="8" maxlength="72" required><small>Between 8 and 72 characters.</small></div><button type="submit" class="btn secondary">Update password ${icon('shield')}</button></form></section></div></div>`;}
function render(){if(!state){renderAuth();return;}destroyCharts();const hash=location.hash.slice(1);current=nav.some(n=>n[0]===hash)?hash:'overview';shell();const views={overview,activities:explore,tracker,analytics,planner,wellness,achievements,profile};$('#content').innerHTML=views[current]()+footer();if(current==='overview')renderOverviewChart();if(current==='analytics')renderAnalyticsCharts();if(current==='tracker')tick();}
function syncTimer(){persistWorkout();if(current==='tracker')render();}
function disableGPS(){if(gpsId!==null)navigator.geolocation.clearWatch(gpsId);gpsId=null;lastPosition=null;}
function haversine(a,b){const rad=n=>n*Math.PI/180;const v=Math.sin(rad(b.latitude-a.latitude)/2)**2+Math.cos(rad(a.latitude))*Math.cos(rad(b.latitude))*Math.sin(rad(b.longitude-a.longitude)/2)**2;return 6371*2*Math.atan2(Math.sqrt(v),Math.sqrt(1-v));}
function enableGPS(){if(!navigator.geolocation){toast('This browser does not support location tracking.',true);return;}if(workout.status!=='running'){toast('Start your workout before enabling GPS.');return;}gpsId=navigator.geolocation.watchPosition(p=>{if(workout.status!=='running'){lastPosition=null;return;}if(p.coords.accuracy>100)return;if(lastPosition){const distance=haversine(lastPosition,p.coords);if(distance<.5)workout.distance+=distance;}lastPosition=p.coords;persistWorkout();if($('#gps-status'))$('#gps-status').textContent='Location access enabled. Distance is being tracked.';},()=>{disableGPS();toast('Location is unavailable or permission was denied. You can continue without GPS.',true);render();},{enableHighAccuracy:true,maximumAge:5000,timeout:15000});render();}
function tick(){if(!state)return;const sec=elapsed();if($('#live-timer')){$('#live-timer').textContent=clock(sec);$('#live-calories').textContent=`${Math.round(activity(workout.activity).met*3.5*state.profile.weight/200*sec/60)} kcal` ;$('#live-distance').textContent=workout.distance.toFixed(2)+' km';$('#workout-progress').style.width=Math.min(100,sec/(workout.target*60)*100)+'%';$('#workout-progress').parentElement.setAttribute('aria-valuenow',Math.min(100,Math.round(sec/(workout.target*60)*100)));$('#workout-target').textContent=sec>=workout.target*60?'Target reached. Finish when you feel ready.':`${Math.floor(sec/60)} of ${workout.target} target minutes`;if($('#rest-count'))$('#rest-count').textContent=restUntil>Date.now()?`Rest · ${Math.ceil((restUntil-Date.now())/1000)} seconds remaining`:restUntil?'Rest complete. Ready for your next set.':'';}if(workout.status==='running')persistWorkout();}
function downloadReport(){const rows=[['Activity','Ended at','Duration seconds','Estimated kcal','Repetitions','Sets','Distance km'],...[...state.workouts].sort((a,b)=>a.endedAt.localeCompare(b.endedAt)).map(w=>[activity(w.activity).name,w.endedAt,w.duration,w.calories,w.reps,w.sets,w.distance])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`sportfit-activity-report-${localDate()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your activity report has been downloaded.');}
async function runAction(action,id,button){switch(action){case 'menu':$('.sidebar').classList.toggle('open');$('.mobile-shade').classList.toggle('open');break;case 'navigate':location.hash=button.dataset.page;break;case 'reminders':{const upcoming=state.plans.filter(p=>!p.completed&&p.date>=localDate()).sort((a,b)=>a.date.localeCompare(b.date));toast(upcoming.length?`Up next: ${activity(upcoming[0].activity).name}, ${niceDate(dateAt(upcoming[0].date))}, ${upcoming[0].duration} minutes.`:'No upcoming sessions yet. Add one to your workout planner.');break;}
case 'logout':if(workout.status!=='idle'){toast('Finish and save your current workout before signing out.');location.hash='tracker';break;}await api('/logout','POST');state=null;csrf=null;sessionId='';sessionStorage.removeItem('sportfit-session');activeOwner=null;disableGPS();renderAuth();break;
case 'period':period=id;render();break;case 'activity-tab':filters.saved=id==='saved';render();break;
case 'save-activity':{const p={...state.profile};p.savedActivities=p.savedActivities.includes(id)?p.savedActivities.filter(x=>x!==id):[...p.savedActivities,id];state.profile=await api('/profile','PUT',p);render();toast(p.savedActivities.includes(id)?'Saved to My Activities.':'Activity removed from your saved list.');break;}
case 'start-activity':if(workout.status!=='idle'&&workout.activity!==id){toast('Finish your current workout before switching activities.');}else if(workout.status==='idle'){workout={activity:id,status:'idle',elapsed:0,since:0,reps:0,sets:0,distance:0,target:activity(id).duration};}if(location.hash==='#tracker')render();else location.hash='tracker';break;
case 'workout-start':workout.target=Number($('#target-minutes').value);if(!Number.isFinite(workout.target)||workout.target<1||workout.target>300){toast('Choose a target between 1 and 300 minutes.',true);break;}workout.status='running';workout.since=Date.now();syncTimer();break;
case 'workout-pause':if(workout.status==='running'){workout.elapsed=elapsed();workout.status='paused';lastPosition=null;}else{workout.status='running';workout.since=Date.now();}syncTimer();break;
case 'workout-stop':{const total=Math.floor(elapsed());if(total<1){toast('Record at least one second before saving.');break;}if(total>86400){toast('The workout exceeded 24 hours. Please start a fresh session.',true);break;}workout.elapsed=total;workout.status='paused';persistWorkout();const saved=await api('/workouts','POST',{activity:workout.activity,duration:total,reps:workout.reps,sets:workout.sets,distance:workout.distance});disableGPS();restUntil=0;workout={activity:workout.activity,status:'idle',elapsed:0,since:0,reps:0,sets:0,distance:0,target:activity(workout.activity).duration};localStorage.removeItem('sportfit-workout:'+activeOwner);await refresh();render();toast(`Session saved. ${clock(saved.duration)} of movement · ~${saved.calories} kcal. Nice work!`);break;}
case 'rep-plus':case 'rep-minus':workout.reps=Math.max(0,Math.min(100000,workout.reps+(action==='rep-plus'?1:-1)));$('#rep-count').textContent=workout.reps;persistWorkout();break;
case 'set-plus':case 'set-minus':workout.sets=Math.max(0,Math.min(1000,workout.sets+(action==='set-plus'?1:-1)));$('#set-count').textContent=workout.sets;persistWorkout();break;
case 'rest':restUntil=Date.now()+60000;tick();break;case 'cancel-rest':restUntil=0;tick();break;
case 'gps':if(gpsId!==null){disableGPS();render();}else enableGPS();break;
case 'export':downloadReport();break;
case 'week-prev':weekOffset--;render();break;case 'week-next':weekOffset++;render();break;case 'week-today':weekOffset=0;render();break;
case 'plan-add':planDialog(null,id);break;case 'plan-edit':planDialog(id);break;case 'close-dialog':$('#modal').close();break;
case 'plan-delete':await api('/plans/'+id,'DELETE');await refresh();render();toast('Session removed from your plan.');break;
case 'plan-complete':{const p=state.plans.find(x=>x.id===id);await api('/plans/'+id,'PUT',{...p,completed:!p.completed});await refresh();render();toast(p.completed?'Session reopened.':'Planned session marked complete.');break;}
case 'generate-plan':{const start=monday(weekOffset),prefs=recommendedActivities();const count=Math.min(7,state.profile.weeklyTarget);let added=0;for(let i=0;i<count;i++){const d=new Date(start);d.setDate(d.getDate()+Math.floor(i*7/count));const date=localDate(d);if(state.plans.some(p=>p.date===date)||state.wellness.some(w=>w.date===date&&w.restDay))continue;await api('/plans','POST',{date,activity:prefs[i%prefs.length],duration:state.profile.level==='beginner'?20:state.profile.level==='intermediate'?35:50,completed:false});added++;}await refresh();render();toast(added?`${added} personalised sessions added. Existing plans and rest days were kept.`:'This week already has a schedule. Try another week or edit your sessions.');break;}
case 'water-add':case 'water-remove':{const w=todayWellness();await api('/wellness','PUT',{...w,water:Math.min(20000,Math.max(0,w.water+(action==='water-add'?250:-250)))});await refresh();render();toast('Hydration record updated.');break;}
}}
document.addEventListener('click',async e=>{const auth=e.target.closest('[data-auth]');if(auth){authMode=auth.dataset.auth;renderAuth();return;}if(e.target.matches('.mobile-shade')){$('.sidebar').classList.remove('open');$('.mobile-shade').classList.remove('open');return;}const b=e.target.closest('[data-action]');if(!b)return;try{b.disabled=true;await runAction(b.dataset.action,b.dataset.id,b);}catch(err){toast(err.message,true);}finally{b.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render();}if(e.target.id==='tracker-activity'){workout.activity=e.target.value;workout.target=activity(workout.activity).duration;render();}});
document.addEventListener('input',e=>{if(e.target.id==='activity-search'){filters.search=e.target.value;const pos=e.target.selectionStart;$('#content').innerHTML=explore()+footer();$('#activity-search').focus();$('#activity-search').setSelectionRange(pos,pos);}if(e.target.id==='height'||e.target.id==='weight'){let f=$('#profile-form');const h=+f.elements.namedItem('height').value,w=+f.elements.namedItem('weight').value;if(h>0&&w>0){$('#bmi-value').textContent=(w/(h/100)**2).toFixed(1);$('#bmi-caption').textContent=`Calculated from ${h} cm and ${w} kg.`;}}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['auth-form','profile-form','password-form','plan-form','wellness-form'].includes(form.id))return;e.preventDefault();const data=new FormData(form),get=k=>data.get(k),num=k=>Number(get(k)),submit=$('[type=submit]',form);submit.disabled=true;try{if(form.id==='auth-form'){
 if(authMode==='forgot'){await api('/password-reset/request','POST',{email:get('email').trim().toLowerCase()});authMode='reset-sent';renderAuth();return;}
 if(authMode==='reset'){if(get('password')!==get('confirmPassword'))throw Error('The passwords do not match.');await api('/password-reset/confirm','POST',{token:resetToken,newPassword:get('password')});resetToken='';state=null;sessionId='';sessionStorage.removeItem('sportfit-session');csrf=null;authMode='login';history.replaceState(null,'',location.pathname+location.search);await getCsrf();renderAuth();toast('Password updated. Sign in with your new password.');return;}
 const email=get('email').trim().toLowerCase(),password=get('password');if(authMode==='register')await api('/register','POST',{name:get('name').trim(),email,password});await getCsrf();const res=await serverFetch('/api/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',[csrf.headerName]:csrf.token},body:new URLSearchParams({username:email,password})});if(!res.ok)throw Error('Email or password is incorrect.');await getCsrf();await refresh();restoreWorkout();render();toast(authMode==='register'?'Welcome to SportFit Pro. Make your profile your own.':'Welcome back. Let’s keep moving.');if(authMode==='register')location.hash='profile';}
if(form.id==='profile-form'){state.profile=await api('/profile','PUT',{...state.profile,name:get('name').trim(),age:num('age'),height:num('height'),weight:num('weight'),level:get('level'),weeklyTarget:num('weeklyTarget'),objective:get('objective'),preferences:data.getAll('preferences')});render();toast('Your profile has been saved.');}
if(form.id==='password-form'){await api('/password','PUT',{currentPassword:get('currentPassword'),newPassword:get('newPassword')});form.reset();toast('Password updated.');}
if(form.id==='plan-form'){const p=state.plans.find(p=>p.id===form.dataset.id);await api('/plans'+(p?'/'+p.id:''),p?'PUT':'POST',{date:get('date'),activity:get('activity'),duration:num('duration'),completed:p?.completed||false});$('#modal').close();await refresh();render();toast('Your session is in the calendar.');}
if(form.id==='wellness-form'){await api('/wellness','PUT',{...todayWellness(),sleep:num('sleep'),intensity:num('intensity'),heartRate:num('heartRate'),recovery:get('recovery'),restDay:data.has('restDay')});await refresh();render();toast('Today’s check-in has been saved.');}
}catch(err){const target=form.id==='auth-form'?$('#auth-error'):form.id==='plan-form'?$('#plan-error'):null;if(target)target.textContent=err.message;else toast(err.message,true);}finally{submit.disabled=false;}});
function restoreWorkout(){activeOwner=state.email;try{const w=JSON.parse(localStorage.getItem('sportfit-workout:'+activeOwner));if(w&&['running','paused'].includes(w.status)&&activities.some(a=>a.id===w.activity)&&Number.isFinite(w.elapsed)&&w.elapsed<=86400){workout={...w,status:'paused',since:0};toast('Your unfinished workout was restored, paused.');}}catch{}}
window.addEventListener('hashchange',async()=>{if(captureResetLink()){state=null;try{await getCsrf();renderAuth();}catch{renderAuth();toast('Unable to connect to the account server.',true);}return;}if(state){render();window.scrollTo(0,0);}});
window.addEventListener('beforeunload',()=>{if(state&&workout.status!=='idle')persistWorkout();disableGPS();});
setInterval(tick,250);
(async()=>{if(API_MISSING){renderAuth();$('#auth-error').textContent='The website is deployed. The account server still needs to be connected.';$('#auth-form button[type=submit]').disabled=true;return;}try{await getCsrf();if(authMode==='reset'){renderAuth();return;}const res=await serverFetch('/api/state');if(res.ok){state=await res.json();restoreWorkout();render();}else renderAuth();}catch{renderAuth();toast('Unable to connect. Please check that the server is running.',true);}})();
